import React from 'react';
import { Link } from 'react-router-dom';

const Register = () => {
  return (
    <div className="container">
      <h1>Register</h1>
      <p>Create a new account</p>
      <Link to="/login">Already have an account? Login</Link>
    </div>
  );
};

export default Register;
